"% Closed-loop step-response metrics (tdm_03)

dt = 0.01;
T  = 30;
t  = 0:dt:T;
N  = length(t);

% System matrices
A_cl = [-0.6, 1.0, 0.1;
        -4.4, -1.6, 0.2;
         1.0, 0.5, -4.0];
B_cl = [0.0; 1.0; 0.5];
C_cl = [1.0, 0.0, 0.0];

% DC value (exact, continuous-time)
y_inf = -C_cl * (A_cl \ B_cl);

% Exact zero-order-hold discretization
I3 = eye(3);
Ad = expm(A_cl * dt);
Bd = A_cl \ ((Ad - I3) * B_cl);

% Simulate step response (u = 1 for all k)
x = zeros(3, N);
for k = 1:N-1
    x(:, k+1) = Ad * x(:, k) + Bd;
end
y = C_cl * x;

% Rise time: first 10% to first 90% crossing of y_inf with linear interpolation
y10 = 0.1 * y_inf;
y90 = 0.9 * y_inf;

idx_10 = find(y >= y10, 1, 'first');
idx_90 = find(y >= y90, 1, 'first');

if ~isempty(idx_10) && idx_10 > 1
    t_10 = t(idx_10-1) + (y10 - y(idx_10-1)) / (y(idx_10) - y(idx_10-1)) * dt;
else
    t_10 = t(max(idx_10, 1));
end

if ~isempty(idx_90) && idx_90 > 1
    t_90 = t(idx_90-1) + (y90 - y(idx_90-1)) / (y(idx_90) - y(idx_90-1)) * dt;
else
    t_90 = t(max(idx_90, 1));
end

rise_time_s = t_90 - t_10;

% Percent overshoot
overshoot_pct = (max(y) - y_inf) / abs(y_inf) * 100;

% Settling time (2%): time of LAST grid sample where |y - y_inf| > 0.02*|y_inf|
err         = abs(y - y_inf);
out_of_band = err > 0.02 * abs(y_inf);
idx_last    = find(out_of_band, 1, 'last');

if isempty(idx_last)
    settling_time_s = 0;
else
    settling_time_s = t(idx_last);
end

% Write result.json
result.rise_time_s     = rise_time_s;
result.overshoot_pct   = overshoot_pct;
result.settling_time_s = settling_time_s;

json_str = jsonencode(result);
fid = fopen('result.json', 'w');
fwrite(fid, json_str);
fclose(fid);"
